SELECT session_date, calculated_uer, daily_average_uer FROM (
    SELECT DATE(seshstart) as session_date,
           (seshviews * engscore) / seshdur as calculated_uer,
           AVG((seshviews * engscore) / seshdur) OVER (PARTITION BY DATE(seshstart)) as daily_average_uer
    FROM sessions
) t WHERE calculated_uer > daily_average_uer ORDER BY session_date;

